package com.marealta.pousada;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.marealta.pousada.dto.*;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.LocalDate;

import static org.junit.jupiter.api.Assertions.*;

public class IntegrationTest {

    private static final String BASE_URL = "http://localhost:7070";
    private final HttpClient client = HttpClient.newHttpClient();
    private final ObjectMapper mapper = new ObjectMapper().registerModule(new JavaTimeModule());

    @Test
    public void testCorporateRatePlanTecnosul() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest(
            201,
            "João Silva",
            "joao@example.com",
            "12345678901",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
            2,
            "CORPORATE",
            "TECNOSUL"
        );

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(request)))
            .build();

        HttpResponse<String> response = client.send(httpRequest, HttpResponse.BodyHandlers.ofString());
        assertEquals(201, response.statusCode());

        ReservationDto reservation = mapper.readValue(response.body(), ReservationDto.class);
        assertEquals(new BigDecimal("779.80"), reservation.subtotal());
        assertEquals(new BigDecimal("93.58"), reservation.discount());
        assertEquals(new BigDecimal("686.22"), reservation.total());
    }

    @Test
    public void testWeekendPackage() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest(
            202,
            "Maria Santos",
            "maria@example.com",
            "98765432100",
            LocalDate.of(2027, 3, 12),
            LocalDate.of(2027, 3, 14),
            2,
            "WEEKEND_PACKAGE",
            null
        );

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(request)))
            .build();

        HttpResponse<String> response = client.send(httpRequest, HttpResponse.BodyHandlers.ofString());
        assertEquals(201, response.statusCode());

        ReservationDto reservation = mapper.readValue(response.body(), ReservationDto.class);
        assertEquals(new BigDecimal("820.00"), reservation.subtotal());
        assertEquals(new BigDecimal("0.00"), reservation.discount());
        assertEquals(new BigDecimal("820.00"), reservation.total());
    }

    @Test
    public void testLongStay() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest(
            101,
            "Pedro Costa",
            "pedro@example.com",
            "11122233344",
            LocalDate.of(2027, 3, 1),
            LocalDate.of(2027, 3, 8),
            1,
            "LONG_STAY",
            null
        );

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(request)))
            .build();

        HttpResponse<String> response = client.send(httpRequest, HttpResponse.BodyHandlers.ofString());
        assertEquals(201, response.statusCode());

        ReservationDto reservation = mapper.readValue(response.body(), ReservationDto.class);
        assertEquals(new BigDecimal("1749.30"), reservation.subtotal());
        assertEquals(new BigDecimal("174.93"), reservation.discount());
        assertEquals(new BigDecimal("1574.37"), reservation.total());
    }

    @Test
    public void testInvalidCorporateCode() throws Exception {
        CreateReservationRequest request = new CreateReservationRequest(
            101,
            "Ana Lima",
            "ana@example.com",
            "55566677788",
            LocalDate.of(2027, 3, 15),
            LocalDate.of(2027, 3, 17),
            1,
            "CORPORATE",
            "INVALID_CODE"
        );

        HttpRequest httpRequest = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL + "/reservations"))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(request)))
            .build();

        HttpResponse<String> response = client.send(httpRequest, HttpResponse.BodyHandlers.ofString());
